<?php
declare(strict_types=1);
define('SAAS_NO_GLOBAL_NAV', true); require_once __DIR__ . '/finance.php';
require_once __DIR__ . '/access.php';
require_once __DIR__ . '/notifications.php';
require_finance_admin();
$pdo = db(); $message = null; $error = null;
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    try {
        $number = trim((string) ($_POST['invoice_number'] ?? '')); $clientId = (int) ($_POST['client_id'] ?? 0); $amount = (float) ($_POST['invoice_amount'] ?? 0); $received = (float) ($_POST['amount_received'] ?? 0); $due = (string) ($_POST['due_date'] ?? '');
        if (!$number || !$clientId || $amount < 0 || $received < 0 || $received > $amount || !$due) { throw new RuntimeException('Enter valid invoice details.'); }
        $pending = $amount - $received; $status = $received >= $amount ? 'Paid' : ($received > 0 ? 'Partially Paid' : (strtotime($due) < strtotime(date('Y-m-d')) ? 'Overdue' : 'Pending'));
        $stmt = $pdo->prepare('SELECT name FROM clients WHERE id = ? AND active = 1'); $stmt->execute([$clientId]); $name = (string) $stmt->fetchColumn(); if (!$name) { throw new RuntimeException('Client not found.'); }
        $pdo->prepare('INSERT INTO client_payments(invoice_number,client_id,client_name,invoice_date,due_date,invoice_amount,amount_received,pending_amount,payment_status,payment_date,payment_mode,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE client_id=VALUES(client_id),client_name=VALUES(client_name),invoice_date=VALUES(invoice_date),due_date=VALUES(due_date),invoice_amount=VALUES(invoice_amount),amount_received=VALUES(amount_received),pending_amount=VALUES(pending_amount),payment_status=VALUES(payment_status),payment_date=VALUES(payment_date),payment_mode=VALUES(payment_mode),notes=VALUES(notes)')->execute([$number, $clientId, $name, $_POST['invoice_date'], $due, $amount, $received, $pending, $status, $received > 0 ? date('Y-m-d') : null, $_POST['payment_mode'] ?? null, trim((string) ($_POST['notes'] ?? ''))]);
        $notify = $pdo->prepare('SELECT u.email FROM users u INNER JOIN clients c ON c.user_id = u.id WHERE c.id = ?'); $notify->execute([$clientId]);
        if ($email = $notify->fetchColumn()) { send_notification((string) $email, 'Invoice ' . $number . ' generated', 'Invoice ' . $number . ' for ' . inr($amount) . ' is available. Due date: ' . $due . '.'); }
        $message = 'Invoice saved and client notification queued.';
    } catch (Throwable $exception) { $error = $exception->getMessage(); }
}
$clients = $pdo->query('SELECT id, name FROM clients WHERE active = 1 ORDER BY name')->fetchAll(); $rows = $pdo->query('SELECT * FROM client_payments ORDER BY invoice_date DESC')->fetchAll();
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Invoices</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="assets/css/session-timeout.css"><link rel="stylesheet" href="assets/css/saas.css"><link rel="stylesheet" href="assets/css/saas.css"></head><body class="saas-body"><div class="saas-shell"><aside class="saas-sidebar"><div class="brand"><span>MT</span> Mega Techzy</div><div class="nav-label">Workspace</div><a class="saas-nav" href="admin_dashboard.php">▦ <span>Overview</span></a><a class="saas-nav" href="finance_dashboard.php">◈ <span>Finance</span></a><a class="saas-nav" href="manage_clients.php">♙ <span>Clients</span></a><a class="saas-nav" href="manage_users.php">♟ <span>Users</span></a><div class="nav-label">Operations</div><a class="saas-nav" href="admin_attendance.php">◷ <span>Attendance</span></a><a class="saas-nav" href="staff_master.php">♙ <span>Staff Master</span></a><a class="saas-nav" href="payroll.php">▤ <span>Payroll</span></a><a class="saas-nav active" href="invoices.php">▧ <span>Invoices</span></a><a class="saas-nav" href="expenses.php">▣ <span>Expenses</span></a><a class="saas-nav" href="cashflow.php">↗ <span>Cash flow</span></a><div class="nav-label">Account</div><a class="saas-nav" href="logout.php">↪ <span>Log out</span></a></aside><main class="saas-main"><div class="d-flex justify-content-between"><h1 class="h3">Client Invoices</h1><a href="admin_dashboard.php">Dashboard</a></div><?php if ($message): ?><div class="alert alert-success"><?= e($message) ?></div><?php endif; ?><?php if ($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post" class="card card-body mb-4"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="row g-3"><div class="col-md-2"><label class="form-label">Invoice no.</label><input class="form-control" name="invoice_number" required></div><div class="col-md-3"><label class="form-label">Client</label><select class="form-select" name="client_id" required><option value="">Select</option><?php foreach ($clients as $client): ?><option value="<?= $client['id'] ?>"><?= e($client['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label class="form-label">Invoice date</label><input class="form-control" type="date" name="invoice_date" value="<?= date('Y-m-d') ?>" required></div><div class="col-md-2"><label class="form-label">Due date</label><input class="form-control" type="date" name="due_date" required></div><div class="col-md-2"><label class="form-label">Amount</label><input class="form-control" type="number" step="0.01" name="invoice_amount" required></div><div class="col-md-2"><label class="form-label">Received</label><input class="form-control" type="number" step="0.01" name="amount_received" value="0"></div><div class="col-md-2"><label class="form-label">Payment mode</label><input class="form-control" name="payment_mode"></div><div class="col-md-8"><label class="form-label">Notes</label><input class="form-control" name="notes"></div><div class="col-12"><button class="btn btn-primary">Save invoice</button></div></div></form><div class="card card-body"><div class="table-responsive"><table class="table"><thead><tr><th>Invoice</th><th>Client</th><th>Amount</th><th>Pending</th><th>Status</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><?= e($row['invoice_number']) ?></td><td><?= e($row['client_name']) ?></td><td><?= inr($row['invoice_amount']) ?></td><td><?= inr($row['pending_amount']) ?></td><td><?= e($row['payment_status']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></main></div></body></html>
